create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null default '', avatar_url text, streaming_defaults jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.personas (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, name text not null check (char_length(name) between 2 and 60), description text check (char_length(description)<=500), thumbnail_url text, status text not null default 'draft' check (status in ('draft','preparing','ready','failed')), face_status text not null default 'missing' check (face_status in ('missing','uploaded','processing','ready','failed')), voice_status text not null default 'missing' check (voice_status in ('missing','uploaded','processing','ready','failed')), consent_face_confirmed_at timestamptz, consent_voice_confirmed_at timestamptz, moderation_status text not null default 'unreviewed' check (moderation_status in ('unreviewed','approved','blocked')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,user_id));
create table public.persona_face_assets (id uuid primary key default gen_random_uuid(), persona_id uuid not null, user_id uuid not null references auth.users on delete cascade, storage_path text not null unique, original_filename text not null, mime_type text not null, file_size bigint not null check(file_size between 1 and 10485760), sort_order int not null default 0, metadata jsonb not null default '{}', created_at timestamptz not null default now(), foreign key(persona_id,user_id) references public.personas(id,user_id) on delete cascade);
create table public.persona_voice_assets (id uuid primary key default gen_random_uuid(), persona_id uuid not null unique, user_id uuid not null references auth.users on delete cascade, storage_path text not null unique, original_filename text not null, mime_type text not null, file_size bigint not null check(file_size between 1 and 52428800), duration_seconds numeric, metadata jsonb not null default '{}', created_at timestamptz not null default now(), foreign key(persona_id,user_id) references public.personas(id,user_id) on delete cascade);
create table public.live_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, persona_id uuid not null, status text not null default 'initializing' check(status in ('initializing','connected','live','stopped','failed')), inference_session_id text, started_at timestamptz, ended_at timestamptz, duration_seconds int not null default 0, latency_ms int, metadata jsonb not null default '{}', created_at timestamptz not null default now(), unique(id,user_id), foreign key(persona_id,user_id) references public.personas(id,user_id) on delete cascade);
create unique index one_active_session on public.live_sessions(user_id) where status in ('initializing','connected','live');
create table public.usage_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, live_session_id uuid references public.live_sessions on delete set null, event_type text not null, quantity numeric not null check(quantity>=0), metadata jsonb not null default '{}', created_at timestamptz not null default now());
create unique index session_usage_once on public.usage_events(live_session_id,event_type);
create table public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users on delete cascade, plan text not null default 'free' check(plan in ('free','creator','pro')), status text not null default 'active', provider text, provider_customer_id text, provider_subscription_id text, current_period_end timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.rate_limits (user_id uuid not null references auth.users on delete cascade, action text not null, window_start timestamptz not null, requests int not null, primary key(user_id,action));
create index personas_owner on public.personas(user_id,created_at desc);
create index faces_owner on public.persona_face_assets(user_id,persona_id);
create index voices_owner on public.persona_voice_assets(user_id,persona_id);
create index sessions_owner on public.live_sessions(user_id,created_at desc);
create index usage_owner on public.usage_events(user_id,created_at desc);
alter table public.personas add column face_preparation_mock boolean not null default false;
alter table public.personas add column voice_preparation_mock boolean not null default false;
create function public.limit_face_assets() returns trigger language plpgsql set search_path='' as $$ begin perform 1 from public.personas where id=new.persona_id for update; if (select count(*) from public.persona_face_assets where persona_id=new.persona_id)>=10 then raise exception 'Maximum 10 face images'; end if; return new; end $$;
create trigger face_asset_cap before insert on public.persona_face_assets for each row execute function public.limit_face_assets();
alter table public.profiles enable row level security;
alter table public.personas enable row level security;
alter table public.persona_face_assets enable row level security;
alter table public.persona_voice_assets enable row level security;
alter table public.live_sessions enable row level security;
alter table public.usage_events enable row level security;
alter table public.subscriptions enable row level security;
alter table public.rate_limits enable row level security;
create policy own_profile_read on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy own_profile_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy own_personas on public.personas for select to authenticated using(user_id=(select auth.uid()));
create policy own_faces on public.persona_face_assets for select to authenticated using(user_id=(select auth.uid()));
create policy own_voices on public.persona_voice_assets for select to authenticated using(user_id=(select auth.uid()));
create policy own_sessions on public.live_sessions for select to authenticated using(user_id=(select auth.uid()));
create policy own_usage on public.usage_events for select to authenticated using(user_id=(select auth.uid()));
create policy own_subscription on public.subscriptions for select to authenticated using(user_id=(select auth.uid()));
-- All processing, consent, billing, asset and session writes are server controlled.
revoke all on public.personas,public.persona_face_assets,public.persona_voice_assets,public.live_sessions,public.usage_events,public.subscriptions,public.rate_limits from anon,authenticated;
grant select on public.personas,public.persona_face_assets,public.persona_voice_assets,public.live_sessions,public.usage_events,public.subscriptions to authenticated;
revoke all on public.profiles from anon,authenticated;
grant select on public.profiles to authenticated;
grant update(display_name,streaming_defaults) on public.profiles to authenticated;
create function public.on_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'display_name',''),80)); insert into public.subscriptions(user_id) values(new.id); return new; end $$;
create trigger create_profile after insert on auth.users for each row execute function public.on_signup();
insert into public.profiles(id) select id from auth.users on conflict do nothing;
insert into public.subscriptions(user_id) select id from auth.users on conflict do nothing;
create function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create trigger touch_persona before update on public.personas for each row execute function public.touch_updated_at();
create function public.derive_persona_status() returns trigger language plpgsql set search_path='' as $$ begin new.status=case when new.face_status='failed' or new.voice_status='failed' then 'failed' when new.face_status='processing' or new.voice_status='processing' then 'preparing' when new.face_status='ready' and new.voice_status in ('ready','missing') then 'ready' else 'draft' end; return new; end $$;
create trigger derive_persona_status before insert or update on public.personas for each row execute function public.derive_persona_status();
create trigger touch_profile before update on public.profiles for each row execute function public.touch_updated_at();
create trigger touch_subscription before update on public.subscriptions for each row execute function public.touch_updated_at();
create function public.consume_rate_limit(action_name text,max_requests int,window_seconds int) returns boolean language plpgsql security definer set search_path='' as $$ declare n int; begin if auth.uid() is null or action_name not in ('persona','upload','process','session','delete') or max_requests<1 or max_requests>60 or window_seconds<60 then return false; end if; insert into public.rate_limits as r(user_id,action,window_start,requests) values(auth.uid(),action_name,now(),1) on conflict(user_id,action) do update set requests=case when r.window_start<now()-make_interval(secs=>window_seconds) then 1 else r.requests+1 end, window_start=case when r.window_start<now()-make_interval(secs=>window_seconds) then now() else r.window_start end returning requests into n; return n<=max_requests; end $$;
revoke execute on function public.consume_rate_limit(text,int,int) from public,anon;
grant execute on function public.consume_rate_limit(text,int,int) to authenticated;
create function public.create_persona(persona_name text,persona_description text,voice_consent boolean) returns uuid language plpgsql security definer set search_path='' as $$ declare p text; cap int; result uuid; begin if auth.uid() is null then raise exception 'Unauthorized'; end if; select plan into p from public.subscriptions where user_id=auth.uid() for update; cap=case p when 'pro' then 20 when 'creator' then 5 else 1 end; if (select count(*) from public.personas where user_id=auth.uid())>=cap then raise exception 'Persona limit reached for your plan'; end if; insert into public.personas(user_id,name,description,consent_face_confirmed_at,consent_voice_confirmed_at) values(auth.uid(),persona_name,persona_description,now(),case when voice_consent then now() else null end) returning id into result; return result; end $$;
revoke execute on function public.create_persona(text,text,boolean) from public,anon;
grant execute on function public.create_persona(text,text,boolean) to authenticated;
-- Only service role may finish sessions and record billed usage atomically.
create function public.finish_session(session_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare s public.live_sessions; seconds int; begin select * into s from public.live_sessions where id=session_id for update; if not found or s.status in ('stopped','failed') then return; end if; seconds=greatest(0,extract(epoch from(now()-coalesce(s.started_at,now())))::int); update public.live_sessions set status='stopped',ended_at=now(),duration_seconds=seconds where id=session_id; insert into public.usage_events(user_id,live_session_id,event_type,quantity) values(s.user_id,s.id,'stream_minutes',seconds/60.0) on conflict do nothing; end $$;
revoke execute on function public.finish_session(uuid) from public,anon,authenticated;
grant execute on function public.finish_session(uuid) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('persona-faces','persona-faces',false,10485760,array['image/jpeg','image/png','image/webp']),('persona-voices','persona-voices',false,52428800,array['audio/mpeg','audio/wav','audio/x-wav','audio/mp4','audio/x-m4a','audio/webm','video/webm']) on conflict(id) do nothing;
-- Storage writes use service-generated signed upload tokens only. Downloads are owner scoped.
create policy own_persona_downloads on storage.objects for select to authenticated using(bucket_id in ('persona-faces','persona-voices') and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.personas p where p.user_id=(select auth.uid()) and p.id::text=(storage.foldername(name))[2]));
